const lockSchedulerFence = `-- name: LockSchedulerFence :one
SELECT lease.build_id, build.run_id, lease.fence_token
FROM ingest.scheduler_lease lease
JOIN ingest.corpus_build build ON build.id = lease.build_id
JOIN ingest.corpus_run run ON run.id = build.run_id
WHERE build.build_uuid = $1
  AND run.run_uuid = $2
  AND lease.owner = $3
  AND lease.fence_token = $4
  AND lease.released_at IS NULL
  AND lease.expires_at > clock_timestamp()
FOR UPDATE OF lease
`

type LockSchedulerFenceParams struct {
	BuildUuid  pgtype.UUID
	RunUuid    pgtype.UUID
	Owner      string
	FenceToken int64
}

type LockSchedulerFenceRow struct {
	BuildID    int64
	RunID      int64
	FenceToken int64
}

// Call inside the unit-of-work transaction before inserting any cross-schema
// outputs. The row lock prevents lease takeover until outputs and stage_result
// commit together. The UUID joins prove the run/build association carried by the
// shard. A missing row is a lost lease and accepts no writes.
func (q *Queries) LockSchedulerFence(ctx context.Context, arg LockSchedulerFenceParams) (LockSchedulerFenceRow, error) {
	row := q.db.QueryRow(ctx, lockSchedulerFence,
		arg.BuildUuid,
		arg.RunUuid,
		arg.Owner,
		arg.FenceToken,
	)
	var i LockSchedulerFenceRow
	err := row.Scan(&i.BuildID, &i.RunID, &i.FenceToken)
	return i, err
}

