const scheduleSourceContentRecheck = `-- name: ScheduleSourceContentRecheck :exec
WITH bumped AS (
    UPDATE ingest.fetch_doc d
    SET state = 'discovered',
        plan_ready = FALSE,
        artifacts_expected = 0,
        artifacts_done = 0,
        artifacts_failed = 0,
        content_recheck_after = $1,
        content_recheck_count = d.content_recheck_count + 1,
        content_recheck_reason = $3,
        updated_at = $4
    WHERE d.id = $5
      AND d.content_recheck_count < $6
      AND NOT (d.state = 'discovered' AND d.plan_ready = FALSE AND d.content_recheck_after IS NOT NULL)
    RETURNING d.id
)
UPDATE ingest.fetch_artifact a
SET state = 'pending',
    lease_owner = NULL,
    lease_expires_at = NULL,
    attempts = 0,
    next_attempt_at = CASE
        WHEN a.kind = 'body' THEN $1
        ELSE $2
    END,
    last_error = $3,
    updated_at = $4
FROM bumped
WHERE a.fetch_doc_id = bumped.id
  AND a.kind IN ('body', 'file')
`

type ScheduleSourceContentRecheckParams struct {
	BodyNextAttemptAt *time.Time
	FileNextAttemptAt *time.Time
	Reason            *string
	UpdatedAt         time.Time
	FetchDocID        int64
	MaxRechecks       int32
}

// Re-open a completed document whose official body/file currently contains only
// placeholder text. Body is due first so Fetch refreshes detail URLs before file
// downloads are re-attempted. max_rechecks bounds eventually-missing source data.
func (q *Queries) ScheduleSourceContentRecheck(ctx context.Context, arg ScheduleSourceContentRecheckParams) error {
	_, err := q.db.Exec(ctx, scheduleSourceContentRecheck,
		arg.BodyNextAttemptAt,
		arg.FileNextAttemptAt,
		arg.Reason,
		arg.UpdatedAt,
		arg.FetchDocID,
		arg.MaxRechecks,
	)
	return err
}

